  sparks(x, y, z, n = 8) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 6 + Math.random() * 8;
      this._spawn(x, y, z, Math.random() < 0.5 ? 0xffd23c : 0xff7a2a, {
        life: 0.35 + Math.random() * 0.3, size: 0.55,
        vx: Math.cos(a) * sp, vz: Math.sin(a) * sp, vy: 2 + Math.random() * 4,
