  gunshot() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const len = 0.14;
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 2400;
    const g = this.ctx.createGain();
    g.gain.value = 0.8;
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(t);
  }

  punch() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(160, t);
    o.frequency.exponentialRampToValueAtTime(60, t + 0.09);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.5, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    o.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.12);
  }

  crash() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const len = 0.25;
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 900;
    const g = this.ctx.createGain();
    g.gain.value = 0.6;
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(t);
  }

  // Short two-tone car horn.
  horn() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [370, 466].forEach((fr) => {
      const o = this.ctx.createOscillator();
      o.type = 'square'; o.frequency.value = fr;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.12, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
      o.connect(g); g.connect(this.sfxGain);
      o.start(t); o.stop(t + 0.4);
    });
  }

  cash() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [880, 1174, 1568].forEach((fr, i) => {
      const o = this.ctx.createOscillator();
      o.type = 'triangle'; o.frequency.value = fr;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t + i * 0.07);
      g.gain.linearRampToValueAtTime(0.22, t + i * 0.07 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.07 + 0.25);
      o.connect(g); g.connect(this.sfxGain);
      o.start(t + i * 0.07); o.stop(t + i * 0.07 + 0.3);
    });
  }

  blip(freq = 660) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'sine'; o.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.2, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    o.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.14);
  }

  nextStation() {
    this.station = (this.station + 1) % STATIONS.length;
    this.step = 0;
    return STATIONS[this.station].name;
  }

  stationName() { return STATIONS[this.station].name; }
